<?php/* * To change this license header, choose License Headers in Project Properties. * To change this template file, choose Tools | Templates * and open the template in the editor. *//** * Description of Comments * * @author Suharshana DsW */class Files {    public $id;    public $file;    public $name;    public $uploaded_on;    public $queue;    public function __construct($id) {        if ($id) {            $query = "SELECT * FROM `files` WHERE `id`=" . $id;            $db = new Database();            $result = mysqli_fetch_array($db->readQuery($query));            $this->id = $result['id'];            $this->file = $result['file'];            $this->name = $result['name'];            $this->uploaded_on = $result['uploaded_on'];            $this->queue = $result['queue'];            return $this;        }    }    public function create() {        $query = "INSERT INTO `files` (`file`,`name`,`uploaded_on`,`queue`) VALUES  ('"                . $this->file . "','"                . $this->name . "',"                . "now(),'"                . $this->queue . "')";        $db = new Database();        $result = $db->readQuery($query);        if ($result) {            return TRUE;        } else {            return FALSE;        }    }    public function all() {        $query = "SELECT * FROM `files` ORDER BY queue ASC";        $db = new Database();        $result = $db->readQuery($query);        $array_res = array();        while ($row = mysqli_fetch_array($result)) {            array_push($array_res, $row);        }        return $array_res;    }    public function update() {        $query = "UPDATE  `files` SET "                . "`file` ='" . $this->file . "'"                . "`name` ='" . $this->name . "'"                . "WHERE `id` = '" . $this->id . "'";        $db = new Database();        $result = $db->readQuery($query);        if ($result) {            return $this->__construct($this->id);        } else {            return FALSE;        }    }    public function GetFilesbyFile($file) {        $query = "SELECT * FROM `files` WHERE `file` = '" . $file . "'";        $db = new Database();        $result = $db->readQuery($query);        $array_res = array();        while ($row = mysqli_fetch_array($result)) {            array_push($array_res, $row);        }        return $array_res;    }    public function delete() {        $query = 'DELETE FROM `files` WHERE id="' . $this->id . '"';        $db = new Database();        return $db->readQuery($query);    }    public function arrange($key, $img) {        $query = "UPDATE `files` SET `queue` = '" . $key . "'  WHERE id = '" . $img . "'";        $db = new Database();        $result = $db->readQuery($query);        return $result;    }}